package br.ucb.claquete.controller;import br.ucb.claquete.service.AcervoJdbcService;import java.time.LocalDate;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api")public class ConsultaRelatorioController{private final AcervoJdbcService s;public ConsultaRelatorioController(AcervoJdbcService s){this.s=s;}@GetMapping("/consultas/{numero}")public List<Map<String,Object>>consulta(@PathVariable int numero){return s.consulta(numero);}@GetMapping("/pesquisas/filmes")public List<Map<String,Object>>pesquisarFilmes(@RequestParam(required=false)String titulo,@RequestParam(required=false)Integer anoMin,@RequestParam(required=false)Integer anoMax,@RequestParam(required=false)String genero){return s.filmes(titulo,anoMin,anoMax,genero);}@GetMapping("/pesquisas/disponibilidade")public List<Map<String,Object>>pesquisarDisponibilidade(@RequestParam(required=false)String plataforma,@RequestParam(required=false)String genero,@RequestParam(required=false)LocalDate vigenteEm){return s.disponibilidades(plataforma,genero,vigenteEm);}@GetMapping("/relatorios")public List<Map<String,Object>>relatorio(){return s.relatorio();}}
